function progress(n,m,d){const w=$('#loadWrap');if(!w||w.hidden)return;const p=$('#loadPct'),b=$('#loadBar'),x=$('#loadMsg'),z=$('#loadDetail');if(p)p.textContent=(n<10?'0':'')+Number(n).toFixed(3)+'%';if(b)b.style.width=Math.min(100,n)+'%';if(x&&m)x.textContent=m;if(z&&d)z.textContent=d}
