function stamp(v){try{const d=new Date(v);if(Number.isNaN(d.getTime()))return '업데이트 시간 미확인';const p=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'numeric',hour12:false}).formatToParts(d),g=t=>p.find(x=>x.type===t)?.value||'';return `${g('year')}.${g('month')}.${g('day')} ${Number(g('hour'))}시 업데이트`}catch{return '업데이트 시간 미확인'}}
