function tickerName(t){const p=arr(D?.top_picks).find(x=>x.ticker===t);return p?.name||D?.details?.[t]?.name||NAMES[t]||t}
function tvSymbol(t){if(/^\d{6}$/.test(t))return `KRX:${t}`;return `${EX[t]||'NASDAQ'}:${t}`}
