function cycleClass(text=''){const s=String(text);if(/붕괴|급락|하락/.test(s))return['하락·붕괴',4];if(/과열|고점|조정/.test(s))return['고점·조정',3];if(/반등|회복|저점.*상승/.test(s))return['저점→반등',1];if(/저점|바닥/.test(s))return['저점 후보',0];if(/상승|주도|구조성장|중간/.test(s))return['상승 중',2];return['구조·상태 평가',-1]}
function tag(text,kind=''){return `<span class="info-tag ${kind}">${esc(text)}</span>`}
function metricPills(items){return `<div class="metric-pills">${items.map(([k,v])=>`<span><small>${esc(k)}</small><b>${esc(fmt(v))}</b></span>`).join('')}</div>`}
function fmtPct(v,d=1){const n=realNum(v);return n==null?'—':`${n>=0?'+':''}${n.toFixed(d)}%`}
